  PregFaq(
    id: 'PREG-SCAN-032',
    number: 130,
    month: 3,
    question: 'What is chorionic villus sampling (CVS), and when is it done?',
    category: 'Scans & Appointments',
    applicability: 'Month 3 (weeks 9 to 13)',
    canI: 'Not applicable',
    sensitivity: 'Yes (light)',
    parts: [
      PregFaqPart(PregFaqSection.direct, '', [
        'Chorionic villus sampling (CVS) is a diagnostic test, usually done between 10 and 13 weeks, that takes a tiny sample of placental tissue to directly check your baby\'s chromosomes. Unlike screening tests, CVS can confirm or rule out a condition, though it carries a small added risk of miscarriage.',
      ], []),
      PregFaqPart(PregFaqSection.direct, 'How It Works', [
        'The placenta develops from the same fertilised egg as your baby, so its cells carry the same genetic information, which is why testing a small placental sample can directly answer questions that screening can only estimate. The sample is taken either through the cervix or through the abdomen, guided by ultrasound, depending on where the placenta sits.',
      ], []),
      PregFaqPart(PregFaqSection.forYou, '', [
        'CVS is optional and usually offered after a higher-risk screening result, due to your age, or because of a family history of a genetic condition; it is not routine for everyone. Preliminary results are often available within about a week, and if there is a problem, a genetic counsellor can talk you through your options.',
      ], []),
      PregFaqPart(PregFaqSection.doctor, '', [
        'Discuss with your doctor whether CVS is right for you, and ask about the miscarriage risk in the context of your specific situation.',
      ], []),
      PregFaqPart(PregFaqSection.perspective, '', [
        'Choosing whether to have a diagnostic test is a genuinely personal decision, and there is no single right answer that suits everyone.',
      ], []),
      PregFaqPart(PregFaqSection.takeaways, '', [], [
        'A diagnostic test, done between 10 and 13 weeks.',
        'Takes a small placental tissue sample to check chromosomes directly.',
        'Can confirm or rule out a condition, unlike screening.',
        'Usually offered after a higher-risk result, due to age, or family history.',
        'Carries a small added risk of miscarriage.',
      ]),
    ],
    related: [
      'PREG-HEALTH-021',
      'PREG-HEALTH-018',
      'PREG-HEALTH-024',
    ],
  ),
  PregFaq(
